import{e as a,ab as t,a1 as o,m as n,r as i,p as s}from"./chunks/framework.BGh0NSIy.js";const u=JSON.parse('{"title":"Monthly Updates [Oct 2024]","description":"October 2024 updates","frontmatter":{"title":"Monthly Updates [Oct 2024]","description":"October 2024 updates","date":"2024-10-01T00:00:00.000Z","next":false,"prev":false,"footer":true},"headers":[],"relativePath":"posts/oct-2024.md","filePath":"posts/oct-2024.md"}'),l={name:"posts/oct-2024.md"};function d(p,e,h,m,f,c){const r=t("Post");return o(),n("div",null,[i(r,{authors:"nbats"}),e[0]||(e[0]=s('<div class="info custom-block"><p class="custom-block-title">INFO</p><p>These update threads only contain major updates. If you&#39;re interested in seeing all minor changes you can follow our <a href="https://github.com/fmhy/FMHYedit/commits/main" target="_blank" rel="noreferrer">Commits Page</a> on GitHub or <a href="https://redd.it/17f8msf" target="_blank" rel="noreferrer">Updates Channel</a> in Discord.</p></div><h3 id="wiki-updates" tabindex="-1">Wiki Updates <a class="header-anchor" href="#wiki-updates" aria-label="Permalink to &quot;Wiki Updates&quot;">​</a></h3><ul><li><p>Did a complete overhaul of the <strong><a href="https://fmhy.net/beginners-guide" target="_blank" rel="noreferrer">Beginners Guide</a></strong>. Removed outdated links, added new sites, and rewrote all the tips.</p></li><li><p>Reorganized the <a href="https://fmhy.net/video#anime-streaming" target="_blank" rel="noreferrer">Anime Streaming</a> section based on <strong><a href="https://challonge.com/Anime_Streaming.svg" target="_blank" rel="noreferrer">tournament results</a></strong>.</p></li><li><p>Reorganized both <a href="https://ibb.co/X7SC3f8" target="_blank" rel="noreferrer">Multi / Single Hosts</a> in the <a href="https://fmhy.net/video" target="_blank" rel="noreferrer">Streaming section</a> as people felt they were somewhat outdated.</p></li><li><p>Added a section for <a href="https://fmhy.net/gaming-tools#steam-deck" target="_blank" rel="noreferrer">Steam Deck</a> in Gaming Tools.</p></li></ul><hr><h3 id="stars-added-⭐" tabindex="-1">Stars Added ⭐ <a class="header-anchor" href="#stars-added-⭐" aria-label="Permalink to &quot;Stars Added ⭐&quot;">​</a></h3><ul><li><p>Starred <a href="https://fmhy.net/video#drives-directories" target="_blank" rel="noreferrer">datadiff</a> in Drives / Directories. Media directory with fast download speed, similar to vadapav / moo.</p></li><li><p>Starred <a href="https://fmhy.net/internet-tools#password-managers" target="_blank" rel="noreferrer">Proton Pass</a> in Password Managers. Feature-rich manager comparable with things like Bitwarden.</p></li><li><p>Starred <a href="https://fmhy.net/video#anime-streaming" target="_blank" rel="noreferrer">Miruro</a> in Anime Streaming. This was the winner of our anime streaming polls.</p></li><li><p>Starred <a href="https://fmhy.net/mobile#modded-apks" target="_blank" rel="noreferrer">RockMods</a> in Modded APKs. RockMods label all their releases correctly and are usually one of the main sources of other groups.</p></li><li><p>Starred <a href="https://fmhy.net/reading#educational-books" target="_blank" rel="noreferrer">OpenStax</a> in Educational Books. Well-organized educational textbook site.</p></li><li><p>Starred <a href="https://fmhy.net/mobile#number-sms" target="_blank" rel="noreferrer">Yet Another Call Blocker</a> in Number / SMS. Hasn&#39;t been updated in a while, but it doesn&#39;t need to be as it&#39;s connected to a crowdsourced number <a href="https://www.shouldianswer.com/" target="_blank" rel="noreferrer">database</a>.</p></li><li><p>Starred <a href="https://fmhy.net/mobile#android-privacy" target="_blank" rel="noreferrer">UrlCheck</a> in Android Privacy. Customizable open-source URL cleaner for Android.</p></li><li><p>Starred <a href="https://fmhy.net/system-tools#wallpapers" target="_blank" rel="noreferrer">Rev Wallpaper</a> in Wallpapers. Reverse wallpaper search engine.</p></li><li><p>Starred <a href="https://fmhy.net/internet-tools#browser-tools" target="_blank" rel="noreferrer">Edge-Remover</a> in Browser Tools. Easy way to uninstall Microsoft Edge.</p></li><li><p>Starred <a href="https://fmhy.net/video#anime-streaming" target="_blank" rel="noreferrer">Akuse</a> in Anime Streaming. Open-source anime app with a nice UI.</p></li><li><p>Starred <a href="https://fmhy.net/video#calendar-upcoming" target="_blank" rel="noreferrer">Movies Countdown</a> in Calendar / Upcoming. Tracks upcoming movie releases, both digital and theater.</p></li><li><p>Starred <a href="https://fmhy.net/storage#tab-managers" target="_blank" rel="noreferrer">Simple Tab Groups</a> in Tab Managers. Feature-rich tab manager with plugin support.</p></li></ul><hr><h3 id="things-removed" tabindex="-1">Things Removed <a class="header-anchor" href="#things-removed" aria-label="Permalink to &quot;Things Removed&quot;">​</a></h3><ul><li><p>Removed Essential from Minecraft mods as they have a history of malicious practices and there are better options anyway.</p></li><li><p>Removed Slider as they&#39;ve been <a href="https://ibb.co/NnY4M8b" target="_blank" rel="noreferrer">shut down</a>.</p></li><li><p>Removed AnimeOut as they&#39;ve closed signups.</p></li><li><p>Unstarred LookMovie as they&#39;ve locked 720p <a href="https://ibb.co/9W50NTg" target="_blank" rel="noreferrer">behind a paywall</a>.</p></li><li><p>Unstarred Modyolo and LiteAPKs as both mislabel releases from other groups as their own and tag apps as newer versions than actually exist in order to get more downloads.</p></li><li><p>Unstarred Gemini as many people consider it less useful than other AI.</p></li><li><p>Unstarred Duolingo as there are better ways to learn languages.</p></li><li><p>Unstarred Tixati as it&#39;s closed-source and there are better options like qBit, Transmission, and Deluge.</p></li></ul>',9))])}const b=a(l,[["render",d]]);export{u as __pageData,b as default};
